package id.simas.mobile;

import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.util.Base64;
import org.json.JSONObject;
import java.io.*;
import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.*;
import java.util.zip.*;

final class ExportFiles {
  static String xml(Object value){String s=String.valueOf(value==null?"":value);return s.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
  static String col(int i){String s="";for(i++;i>0;i=(i-1)/26)s=(char)('A'+(i-1)%26)+s;return s;}
  static void zip(ZipOutputStream z,String name,String content)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(content.getBytes("UTF-8"));z.closeEntry();}
  static float weight(String h){if(h.equals("No."))return .42f;if(h.equals("RT")||h.equals("RW"))return .48f;if(h.contains("Catatan")||h.contains("Keterangan")||h.contains("Deskripsi")||h.contains("Rincian"))return 1.8f;if(h.contains("Nama")||h.contains("Dusun")||h.contains("Jenis"))return 1.35f;return 1f;}
  static byte[] xlsx(JSONObject mosque,ExportTable... tables)throws Exception{
    String ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main",rel="http://schemas.openxmlformats.org/package/2006/relationships";
    ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){
      StringBuilder types=new StringBuilder("<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>");
      StringBuilder book=new StringBuilder("<workbook xmlns=\""+ns+"\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>"),rels=new StringBuilder("<Relationships xmlns=\""+rel+"\">");
      for(int i=0;i<tables.length;i++){types.append("<Override PartName=\"/xl/worksheets/sheet"+(i+1)+".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");book.append("<sheet name=\""+(i==0?"Laporan":"Data Sumber")+"\" sheetId=\""+(i+1)+"\" r:id=\"rId"+(i+1)+"\"/>");rels.append("<Relationship Id=\"rId"+(i+1)+"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet"+(i+1)+".xml\"/>");zip(z,"xl/worksheets/sheet"+(i+1)+".xml",sheet(mosque,tables[i],ns));}
      zip(z,"[Content_Types].xml",types+"</Types>");zip(z,"_rels/.rels","<Relationships xmlns=\""+rel+"\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
      zip(z,"xl/workbook.xml",book+"</sheets></workbook>");zip(z,"xl/_rels/workbook.xml.rels",rels+"<Relationship Id=\"styles\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
      zip(z,"xl/styles.xml","<styleSheet xmlns=\""+ns+"\"><numFmts count=\"1\"><numFmt numFmtId=\"164\" formatCode=\"#,##0.###\"/></numFmts><fonts count=\"3\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"16\"/><name val=\"Calibri\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFE4ECE7\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"2\"><border/><border><left style=\"thin\"/><right style=\"thin\"/><top style=\"thin\"/><bottom style=\"thin\"/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"6\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"1\" xfId=\"0\" applyAlignment=\"1\"><alignment vertical=\"top\" wrapText=\"1\"/></xf><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"1\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"1\" xfId=\"0\" applyAlignment=\"1\"><alignment horizontal=\"center\" vertical=\"center\" wrapText=\"1\"/></xf><xf numFmtId=\"164\" fontId=\"1\" fillId=\"2\" borderId=\"1\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"0\" fontId=\"2\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment horizontal=\"center\" wrapText=\"1\"/></xf><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment horizontal=\"center\" wrapText=\"1\"/></xf></cellXfs></styleSheet>");
    }return out.toByteArray();
  }
  static String sheet(JSONObject m,ExportTable t,String ns){
    ArrayList<Object[]> all=new ArrayList<>();all.add(new Object[]{ExportTable.s(m,"name")});all.add(new Object[]{ExportTable.s(m,"address")});all.add(new Object[]{ExportTable.s(m,"city")+(ExportTable.s(m,"phone").isEmpty()?"":" · Tel. "+ExportTable.s(m,"phone"))});all.add(new Object[]{t.title});all.add(new Object[]{t.context});all.add(new Object[]{});all.add(t.headers);all.addAll(t.rows);all.addAll(t.totals);
    int signature=-1;if(t.signatures){all.add(new Object[]{});signature=all.size();Object[] r=new Object[t.headers.length];Arrays.fill(r,"");r[0]="Pembuat";r[r.length/2]="Mengetahui";all.add(r);all.add(new Object[]{});all.add(new Object[]{});Object[] n=r.clone();n[0]="(____________________)";n[n.length/2]="(____________________)";all.add(n);}
    StringBuilder s=new StringBuilder("<worksheet xmlns=\""+ns+"\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"7\" topLeftCell=\"A8\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>");
    for(int c=0;c<t.headers.length;c++)s.append("<col min=\""+(c+1)+"\" max=\""+(c+1)+"\" width=\""+(weight(t.headers[c])*18)+"\" customWidth=\"1\"/>");s.append("</cols><sheetData>");
    for(int r=0;r<all.size();r++){s.append("<row r=\""+(r+1)+"\""+(r<5?" ht=\"30\" customHeight=\"1\"":r==6?" ht=\"36\" customHeight=\"1\"":"")+">");Object[] row=all.get(r);for(int c=0;c<row.length;c++){Object v=row[c]==null?"":row[c];boolean numeric=v instanceof Number;int style=r<5?(r==0||r==3?4:5):r==6?2:r>=7+t.rows.size()&&r<7+t.rows.size()+t.totals.size()?(numeric?3:2):r>=signature&&signature>=0?5:numeric?1:0;s.append("<c r=\""+col(c)+(r+1)+"\" s=\""+style+"\"");if(numeric)s.append("><v>"+xml(v)+"</v></c>");else s.append(" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+xml(v)+"</t></is></c>");}s.append("</row>");}
    s.append("</sheetData>");if(!t.rows.isEmpty())s.append("<autoFilter ref=\"A7:"+col(t.headers.length-1)+(7+t.rows.size())+"\"/>");ArrayList<String> merges=new ArrayList<>();for(int i=1;i<=5;i++)merges.add("A"+i+":"+col(t.headers.length-1)+i);if(signature>=0)for(int i:new int[]{signature+1,signature+4}){merges.add("A"+i+":"+col(t.headers.length/2-1)+i);merges.add(col(t.headers.length/2)+i+":"+col(t.headers.length-1)+i);}s.append("<mergeCells count=\""+merges.size()+"\">");for(String merge:merges)s.append("<mergeCell ref=\""+merge+"\"/>");s.append("</mergeCells><printOptions horizontalCentered=\"1\"/><pageMargins left=\"0.3\" right=\"0.3\" top=\"0.4\" bottom=\"0.4\" header=\"0.2\" footer=\"0.2\"/><pageSetup paperSize=\"9\" orientation=\"landscape\" fitToWidth=\"1\" fitToHeight=\"0\"/></worksheet>");return s.toString();
  }
  static String display(Object o){if(o instanceof BigDecimal)return new DecimalFormat("#,##0.###",DecimalFormatSymbols.getInstance(new Locale("id","ID"))).format(o);return String.valueOf(o==null?"":o);}
  static ArrayList<String> wrap(String text,Paint p,float width){ArrayList<String> out=new ArrayList<>();for(String line:text.split("\n",-1)){if(line.isEmpty()){out.add("");continue;}while(!line.isEmpty()){int n=p.breakText(line,true,width,null);n=Math.max(1,n);if(n<line.length()){int space=line.lastIndexOf(' ',n);if(space>n/2)n=space;}out.add(line.substring(0,n));line=line.substring(n).trim();}}return out;}
  static byte[] pdf(JSONObject mosque,ExportTable t,String date)throws Exception{
    PdfDocument doc=new PdfDocument();Painter p=new Painter(doc,mosque,t,date);try{p.start();for(Object[] row:t.rows)p.row(row,false);if(t.rows.isEmpty())p.message("Tidak ada data sesuai filter.");for(Object[] row:t.totals)p.row(row,true);if(t.signatures){if(p.y+105>p.bottom)p.next();p.y+=25;p.center("Pembuat",p.width*.28f,p.y,10,true);p.center("Mengetahui",p.width*.72f,p.y,10,true);p.y+=65;p.center("(____________________)",p.width*.28f,p.y,10,false);p.center("(____________________)",p.width*.72f,p.y,10,false);}p.finish();ByteArrayOutputStream b=new ByteArrayOutputStream();doc.writeTo(b);return b.toByteArray();}finally{doc.close();}
  }
  static final class Painter {
    final PdfDocument doc;final JSONObject mosque;final ExportTable t;final String date;final Paint ink=new Paint(3);final int width,height;final float left=30,bottom;float y;float[] widths;int number=0;PdfDocument.Page page;Canvas canvas;
    Painter(PdfDocument d,JSONObject m,ExportTable t,String date){doc=d;mosque=m;this.t=t;this.date=date;width=t.headers.length>6?842:595;height=t.headers.length>6?595:842;bottom=height-42;widths=new float[t.headers.length];float total=0;for(String h:t.headers)total+=weight(h);for(int i=0;i<widths.length;i++)widths[i]=(width-60)*weight(t.headers[i])/total;}
    void center(String s,float x,float y,float size,boolean bold){ink.setColor(0xff20372c);ink.setTextSize(size);ink.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);canvas.drawText(s,x-ink.measureText(s)/2,y,ink);}
    void start(){page=doc.startPage(new PdfDocument.PageInfo.Builder(width,height,++number).create());canvas=page.getCanvas();y=30;
      String logo=ExportTable.s(mosque,"logo_data_url");if(logo.startsWith("data:image/")&&logo.contains(";base64,")&&logo.length()<400000){try{byte[] bytes=Base64.decode(logo.substring(logo.indexOf(',')+1),Base64.DEFAULT);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/160);o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(b!=null){float scale=Math.min(45f/b.getWidth(),45f/b.getHeight());canvas.drawBitmap(b,null,new RectF(left,y,left+b.getWidth()*scale,y+b.getHeight()*scale),ink);b.recycle();}}catch(Exception ignored){}}
      ink.setTextSize(15);ink.setTypeface(Typeface.DEFAULT_BOLD);for(String line:wrap(ExportTable.s(mosque,"name"),ink,width-180)){center(line,width/2f,y+15,15,true);y+=18;}ink.setTextSize(9);ink.setTypeface(Typeface.DEFAULT);for(String line:wrap(ExportTable.s(mosque,"address")+" "+ExportTable.s(mosque,"city"),ink,width-180)){center(line,width/2f,y+10,9,false);y+=12;}if(!ExportTable.s(mosque,"phone").isEmpty()){center("Tel. "+ExportTable.s(mosque,"phone"),width/2f,y+10,9,false);y+=12;}y=Math.max(y+8,88);ink.setColor(0xff214d3b);canvas.drawLine(left,y,width-left,y,ink);y+=18;ink.setTextSize(12);ink.setTypeface(Typeface.DEFAULT_BOLD);for(String line:wrap(t.title,ink,width-60)){center(line,width/2f,y,12,true);y+=15;}ink.setTextSize(8);ink.setTypeface(Typeface.DEFAULT);for(String line:wrap(t.context,ink,width-60)){center(line,width/2f,y,8,false);y+=11;}y+=8;row(t.headers,true);
    }
    void finish(){ink.setTextSize(8);ink.setTypeface(Typeface.DEFAULT);ink.setColor(0xff728377);canvas.drawText("Dicetak "+date+" · SIMASJID",left,height-20,ink);String s="Halaman "+number;canvas.drawText(s,width-left-ink.measureText(s),height-20,ink);doc.finishPage(page);}
    void next(){finish();start();}
    void message(String s){if(y+25>bottom)next();ink.setTextSize(9);ink.setColor(0xff20372c);canvas.drawText(s,left+5,y+15,ink);y+=25;}
    void row(Object[] cells,boolean bold){ink.setTextSize(8);ink.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);ArrayList<ArrayList<String>> lines=new ArrayList<>();int count=1;for(int i=0;i<widths.length;i++){ArrayList<String> l=wrap(display(i<cells.length?cells[i]:""),ink,widths[i]-8);lines.add(l);count=Math.max(count,l.size());}int offset=0;while(offset<count){if(bottom-y<25)next();int fit=Math.max(1,(int)((bottom-y-8)/11));int take=Math.min(fit,count-offset);float h=take*11+8,x=left;for(int i=0;i<widths.length;i++){ink.setColor(bold?0xffe4ece7:0xffffffff);ink.setStyle(Paint.Style.FILL);canvas.drawRect(x,y,x+widths[i],y+h,ink);ink.setColor(0xffb9c8bf);ink.setStrokeWidth(.5f);ink.setStyle(Paint.Style.STROKE);canvas.drawRect(x,y,x+widths[i],y+h,ink);ink.setStyle(Paint.Style.FILL);ink.setColor(0xff20372c);ink.setTextSize(8);ink.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);for(int k=0;k<take&&offset+k<lines.get(i).size();k++){String text=lines.get(i).get(offset+k);boolean numeric=i<cells.length&&cells[i] instanceof Number;canvas.drawText(text,numeric?x+widths[i]-4-ink.measureText(text):x+4,y+12+k*11,ink);}x+=widths[i];}y+=h;offset+=take;if(offset<count)next();}}
  }
}
